import React, { useEffect, useRef } from 'react';
import { View, Text, Animated, StyleSheet } from 'react-native';

export default function {{component_name}}({ {{bpm_prop}} = 72 }) {
  const scale = useRef(new Animated.Value(1)).current;
  useEffect(() => {
    const interval = 60000 / {{bpm_prop}};
    const loop = Animated.loop(Animated.sequence([
      Animated.timing(scale, { toValue: 1.25, duration: interval / 2, useNativeDriver: true }),
      Animated.timing(scale, { toValue: 1, duration: interval / 2, useNativeDriver: true }),
    ]));
    loop.start();
    return () => loop.stop();
  }, [{{bpm_prop}}]);

  return (
    <View style={styles.row}>
      <Animated.Text style={[styles.heart, { transform: [{ scale }] }]}>♥</Animated.Text>
      <Text style={styles.bpm}>{{{bpm_prop}}} <Text style={styles.unit}>BPM</Text></Text>
    </View>
  );
}
const styles = StyleSheet.create({
  row: { flexDirection: 'row', alignItems: 'center', padding: 16 },
